@Test
public void testConcurrenceGetRemoteClientAndRefresh() throws Exception {
    //guarantee has any client in clientManager
    this.refresh();
    CyclicBarrier cyclicBarrier = new CyclicBarrier(3, () -> {
        log.debug("begin concurrency test");
    });
    final ExecutorService executorService = Executors.newFixedThreadPool(3);
    final Future<?> refreshFuture = executorService.submit(() -> {
        try {
            cyclicBarrier.await();
            this.refresh();
        } catch (InterruptedException | BrokenBarrierException e) {
            e.printStackTrace();
        }
    });
    executorService.submit(() -> {
        try {
            int i = 0;
            cyclicBarrier.await();
            while (!refreshFuture.isDone()) {
                Assertions.assertFalse(this.clientManager.getRemoteClient().isEmpty());
                log.debug("thread {} invoke {} times", Thread.currentThread().getName(), i++);
            }
        } catch (InterruptedException | BrokenBarrierException e) {
            e.printStackTrace();
        }
    });
    try {
        int i = 0;
        cyclicBarrier.await();
        while (!refreshFuture.isDone()) {
            Assertions.assertFalse(this.clientManager.getRemoteClient().isEmpty());
            log.debug("thread {} invoke {} times", Thread.currentThread().getName(), i++);
        }
    } catch (InterruptedException | BrokenBarrierException e) {
        e.printStackTrace();
    }
