    request.setDsl("" + "filter {\n" + "  json {" + "  }\n" + "  extractor {\n" + "    timestamp parsed.time as String, \"yyyy-MM-dd'T'HH:mm:ssXXX\"\n" + "  }\n" + "  sink {\n" + "  }\n" + "}");
    final LogTestResponse response = query.test(request);
    assertEquals(1698928776000L, response.getLog().getTimestamp());
}

